class Task:
    def __init__(self, C_i, S_i, D_i, T_i):
        self.C_i = C_i
        self.S_i = S_i
        self.D_i = D_i
        self.T_i = T_i

def calculate_utilization(task_set):
    total_U = 0
    for tau_i in task_set:
        U_i = tau_i.C_i / tau_i.T_i
        total_U += U_i
    return total_U

def is_schedulable(task_set, PI_values):
    for i in range(len(task_set)):
        R_i = compute_WCRT_EL(task_set[i], task_set, PI_values)
        if R_i > task_set[i].D_i:
            return False
    return True

def optimize_EL_parameters(task_set, max_iter=200):
    PI = [tau.D_i for tau in task_set]
    for _ in range(max_iter):
        R = [compute_WCRT_EL(tau, task_set, PI) for tau in task_set]
        if all(R[i] <= task_set[i].D_i for i in range(len(task_set))):
            return PI, True

        indices_to_update = [i for i in range(len(task_set)) if R[i] < task_set[i].D_i]
        for i in indices_to_update:
            PI[i] = PI[i] + (task_set[i].D_i - R[i])
    return PI, False
